b=$S/render/runtime/synthesizer.md
for s in 'lone_pr_land = "direct"' 'exactly one ready PR lands immediately' 'no update-branch, no' 'Only the tested-with-default-branch gate is waived.' 'Tested-with-default-branch waiver: lone_pr_land=direct, exactly one ready PR' 'two or more ready PRs use a merge train,' 'wait for the default-branch push CI run at that exact SHA;' 'blocked: main red after #<n> <run-url>'; do grep -qF -- "$s" $b && echo "brief: $s" || { echo "missing in brief: $s"; exit 1; }; done

