g checkout -q main && echo m > $R/m.txt && g add m.txt && g commit -qm "main moves" && g push -q origin main && g checkout -q --detach || exit 1
M=$(tip); H=$(h 5); git -C $O merge-base --is-ancestor $M $H && exit 1; echo "pr=5 head $H is behind main $M"
X="--org-profile {state_dir}/direct.toml"; $C land-lock acquire $P >/dev/null || exit 1
ok 5 && $C train check 5 $P $X | grep -q 'name=tested-base status=manual' && gh pr merge 5 $Q --squash --match-head-commit $H; rc=$?
$C land-lock release $P >/dev/null; test $rc = 0 || exit 1
echo "direct land: merge=$(tip) merge^=$(git -C $O rev-parse $(tip)^) files=$(git -C $O ls-tree --name-only $(tip) | tr '\n' ' ')"
test "$(git -C $O rev-parse $(tip)^)" = $M && git -C $O cat-file -e $(tip):f5.txt && git -C $O cat-file -e $(tip):m.txt && ! grep -q "update-branch\|^pr create" $L && echo "no update-branch, no train PR"

