ok 6 && ok 7 || exit 1
out=$($C train build 6 7 $P $T); echo "$out" | grep "^member\|^train n="; k=$(echo "$out" | sed -n "s/^train n=\([0-9]*\) .*ci=pass$/\1/p")
test -n "$k" && $C train land $k 6 $P $T | grep "^landed" && $C train land $k 7 $P $T | grep "^landed\|^train n=" && grep -q "^pr create .*--draft.*--head crew/train-$k " $L

