B=$(cat $G/base); H=$(h 8)
stop 8 'no approval verdict at head' verdict=$B || exit 1
stop 8 'no approval verdict at head' "review=CHANGES_REQUESTED|<!-- crew:v1 role=reviewer-validator pass=verdict pr=8 sha=$H base=$B round=2 verdict=changes -->" || exit 1
stop 8 'state tag crew:hold' label=crew:hold || exit 1
stop 8 'open rereview at head' "review=COMMENTED|<!-- crew:v1 role=coordinator pass=steer cmd=rereview pr=8 sha=$H -->" || exit 1
stop 8 'open coordinator hold-until-#30' "comment=[Ash/hold] hold-until-#30 <!-- crew:v1 role=coordinator pass=steer cmd=hold pr=8 sha=$H -->" || exit 1
stop 8 'crew:sensitive needs owner merge-ok at head' label=crew:sensitive ok=$B || exit 1
stop 8 'no merge permission' ok=none || exit 1
stop 8 'not mergeable' mergeable=CONFLICTING || exit 1
stop 8 'PR is CLOSED' state=CLOSED || exit 1
echo '{"issues/1/comments": "garbage"}' > $G/api.json; X="--org-profile {state_dir}/own.toml"
stop 8 'ownership: read-only; refusing land' || exit 1
rm $G/api.json; X=; k=$(train 8) && m=$(tip) && $C train land $k 8 $P $T | grep "^landed pr=8 head=$H " && test "$(git -C $O rev-parse $(tip)^)" = $m && test $(grep -c "^pr merge 8 " $L) = 1

