echo "merge at checked head: exit $rc $out"; test $rc = 1 && test "$(tip)" = $m || exit 1
$V 9 $N verdict=$H ok=$H; out=$($C train check 9 $P $X); echo "$out" | grep status=blocked | sed "s/^gate pr=[0-9]* sha=[0-9a-f]* //"; echo "$out" | grep -q "name=verdict status=blocked" && echo "$out" | grep -q "no approval verdict at head"
